InputMethodHostAsyncWaiter::InputMethodHostAsyncWaiter(
    InputMethodHost* proxy) : proxy_(proxy) {}

InputMethodHostAsyncWaiter::~InputMethodHostAsyncWaiter() = default;

void InputMethodHostAsyncWaiter::RequestSuggestions(
    SuggestionsRequestPtr request, SuggestionsResponsePtr* out_response) {
  base::RunLoop loop;
  proxy_->RequestSuggestions(std::move(request),
      base::BindOnce(
          [](base::RunLoop* loop,
             SuggestionsResponsePtr* out_response
,
             SuggestionsResponsePtr response) {*out_response = std::move(response);
            loop->Quit();
          },
          &loop,
          out_response));
  loop.Run();
}

SuggestionsResponsePtr InputMethodHostAsyncWaiter::RequestSuggestions(
    SuggestionsRequestPtr request) {
  SuggestionsResponsePtr async_wait_result;
  RequestSuggestions(std::move(request),&async_wait_result);
  return async_wait_result;
}






